INSERT INTO system_settings (category, setting_key, setting_value) VALUES
('email-template', 'cgso-review', '{"name":"Semakan CGSO","subject":"Permohonan untuk semakan CGSO - {{applicationNo}}","body":"<p>Tuan/Puan,</p><p>Petugas telah menyemak permohonan ini dan menghantarnya untuk semakan CGSO.</p><p><b>No. Permohonan:</b> {{applicationNo}}</p><p>Log masuk untuk melihat butiran permohonan: {{link}}</p>","enabled":true}'),
('email-template', 'kpp-review', '{"name":"Semakan KPP","subject":"Permohonan untuk semakan KPP - {{applicationNo}}","body":"<p>Tuan/Puan,</p><p>CGSO telah membuat semakan dan menghantar permohonan ini kepada KPP Cawangan Pengeluaran.</p><p><b>No. Permohonan:</b> {{applicationNo}}</p><p>Log masuk untuk melihat butiran permohonan: {{link}}</p>","enabled":true}'),
('email-template', 'kpp-feedback', '{"name":"Maklum Balas KPP","subject":"Maklum balas KPP diterima - {{applicationNo}}","body":"<p>Tuan/Puan,</p><p>KPP Cawangan Pengeluaran telah memberi maklum balas untuk permohonan ini.</p><p><b>No. Permohonan:</b> {{applicationNo}}</p><p>Log masuk untuk melihat butiran permohonan: {{link}}</p>","enabled":true}'),
('email-template', 'visit-completed', '{"name":"Lawatan Selesai","subject":"Lawatan selesai - {{applicationNo}}","body":"<p>Tuan/Puan,</p><p>Penyelia loji telah mengemas kini ulasan dan menandakan lawatan ini sebagai selesai.</p><p><b>No. Permohonan:</b> {{applicationNo}}</p><p>Log masuk untuk melihat butiran permohonan: {{link}}</p>","enabled":true}'),
('email-template', 'staff-decision-approved', '{"name":"Keputusan Diluluskan untuk Petugas","subject":"Permohonan diluluskan - {{applicationNo}}","body":"<p>Tuan/Puan,</p><p>Pengarah telah meluluskan permohonan ini dan pas telah dikeluarkan.</p><p><b>No. Permohonan:</b> {{applicationNo}}</p><p>Log masuk untuk melihat butiran permohonan: {{link}}</p>","enabled":true}'),
('email-template', 'staff-decision-rejected', '{"name":"Keputusan Ditolak untuk Petugas","subject":"Permohonan ditolak - {{applicationNo}}","body":"<p>Tuan/Puan,</p><p>Pengarah telah menolak permohonan ini.</p><p><b>No. Permohonan:</b> {{applicationNo}}</p><p>Log masuk untuk melihat butiran permohonan: {{link}}</p>","enabled":true}');
